// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { cva, type VariantProps } from "class-variance-authority";
import { Slot } from "@/lib/primitives";
import { IconSizeProvider, useInk, useMergedRef } from "@/lib/ink/vue";
import { badgeRecipe, tallyWidth, type BadgeTone } from "@/lib/ink/recipes/badge-ink";
import { cn } from "@/lib/utils";
const badgeVariants = cva("relative isolate inline-flex w-fit shrink-0 items-center justify-center gap-1 font-hand font-bold whitespace-nowrap select-none [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not(.absolute):not([class*='size-'])]:size-3.5", {
  variants: {
    variant: {
      default: "text-primary-foreground" as const,
      secondary: "text-secondary-foreground" as const,
      destructive: "text-paper" as const,
      outline: "text-foreground" as const,
      ghost: "text-foreground" as const,
      link: "text-link hover:text-link-hover" as const
    },
    size: {
      sm: "h-5 px-2 text-[13px] leading-none [&:is(a,button)]:after:absolute [&:is(a,button)]:after:inset-x-0 [&:is(a,button)]:after:-inset-y-0.5 has-[>svg:not(.absolute)]:ps-1.5 [&_svg:not(.absolute):not([class*='size-'])]:size-3" as const,
      default: "h-6 px-2.5 text-sm leading-none has-[>svg:not(.absolute)]:ps-2 calm:h-5 calm:[&:is(a,button)]:after:absolute calm:[&:is(a,button)]:after:inset-x-0 calm:[&:is(a,button)]:after:-inset-y-0.5" as const,
      lg: "h-7 px-3 text-base leading-none has-[>svg:not(.absolute)]:ps-2.5 [&_svg:not(.absolute):not([class*='size-'])]:size-4" as const
    }
  },
  defaultVariants: {
    variant: "default" as const,
    size: "default" as const
  }
});
const BADGE_H = {
  sm: 20,
  default: 24,
  lg: 28
} as const;
const ICON_PX = {
  sm: 12,
  default: 14,
  lg: 16
} as const;
const TALLY_MAX = 20;
const Badge = defineUi<UI.ComponentProps<"span"> & VariantProps<typeof badgeVariants> & {
  asChild?: boolean;
  tone?: BadgeTone;
  count?: number;
  max?: number;
  tally?: boolean;
  seed?: string | number;
}>("Badge", ["class", "variant", "size", "tone", "count", "max", "tally", "asChild", "seed"], (_props, {
  slots: _slots
}) => {
  const className = computed(() => _props["class"]);
  const variant = computed(() => _props["variant"]);
  const size = computed(() => _props["size"]);
  const tone = computed(() => _props["tone"]);
  const count = computed(() => _props["count"]);
  const max = computed(() => _props["max"] === undefined ? 99 : _props["max"]);
  const tally = computed(() => _props["tally"] === undefined ? false : _props["tally"]);
  const asChild = computed(() => _props["asChild"] === undefined ? false : _props["asChild"]);
  const seed = computed(() => _props["seed"]);
  const children = renderValue(() => readSlot(_slots.default));
  const ref = computed(() => _props["ref"]);
  const props = computed(() => omitProps(_props, ["class", "variant", "size", "tone", "count", "max", "tally", "asChild", "seed", "children", "ref"]));
  const v = computed(() => variant.value ?? "default");
  const s = computed(() => size.value ?? "default");
  const tallied = computed(() => !asChild.value && tally.value && count.value !== undefined && count.value > 0 && count.value <= TALLY_MAX);
  const hoverable = computed(() => asChild.value || typeof props.value.onClick === "function");
  const {
    hostRef,
    hostProps,
    node
  } = useInk(() => ({
    recipe: badgeRecipe,
    params: {
      variant: v.value,
      size: s.value,
      tone: tone.value,
      tally: tallied.value ? count.value : undefined,
      hoverable: hoverable.value
    },
    kind: "chip" as const,
    seed: seed.value
  }));
  const mergedRef = computed(() => useMergedRef<HTMLElement>(hostRef, ref.value as UI.Ref<HTMLElement> | undefined));
  const shared = computed(() => ({
    "data-variant": v.value,
    "data-size": s.value,
    ref: mergedRef.value,
    ...hostProps.value,
    ...props.value
  }));
  const iconPx = computed(() => ICON_PX[s.value]);
  return () => {
    if (asChild.value) {
      return <IconSizeProvider value={iconPx.value}>
        <Slot.Root data-slot="badge" {...domProps(shared.value)} class={cn(badgeVariants({
          variant: v.value,
          size: s.value
        }), className.value)}>
          <Slot.Slottable>{readSlot(_slots.default)}</Slot.Slottable>
          {node.value}
        </Slot.Root>
      </IconSizeProvider>;
    }
    const shown = readSlot(_slots.default) ?? (count.value === undefined ? undefined : count.value > max.value ? `${max.value}+` : String(count.value));
    return <IconSizeProvider value={iconPx.value}>
      <span data-slot="badge" {...domProps(shared.value)} class={cn(badgeVariants({
        variant: v.value,
        size: s.value
      }), count.value !== undefined && "ll-num min-w-6 px-1.5", className.value)}>
        {node.value}
        {tallied.value ? <>
            <span class="sr-only">{shown}</span>
            <span aria-hidden="true" data-slot="badge-tally" class="inline-block h-full" style={cssStyle({
            width: tallyWidth(count.value, BADGE_H[s.value])
          })} />
          </> : shown}
      </span>
    </IconSizeProvider>;
  };
});
export { Badge, badgeVariants };

import { blobFill, highlight, wash } from '@/lib/ink/fills'
import { pillPoly } from '@/lib/ink/geom'
import { tallyLines, box, focusRing, underline, RULER } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'
import type { PaintKey } from '@/lib/ink/paint'

export const badgeVariantList = ['default', 'secondary', 'destructive', 'outline', 'ghost', 'link'] as const
export const badgeSizeList = ['sm', 'default', 'lg'] as const
export const badgeToneList = ['marker', 'hi', 'tangerine', 'lemon', 'grass', 'teal', 'sky', 'bubblegum'] as const
export type BadgeVariant = (typeof badgeVariantList)[number]
export type BadgeSize = (typeof badgeSizeList)[number]
export type BadgeTone = (typeof badgeToneList)[number]

export interface BadgeParams {
  variant: BadgeVariant
  size: BadgeSize
  tone?: BadgeTone
  tally?: number
  hoverable?: boolean
}

const LABEL_PX: Record<BadgeSize, number> = { sm: 13, default: 14, lg: 16 }

export const tallyHeight = (h: number): number => Math.round(h * 0.62)

export function tallyWidth(count: number, h: number): number {
  const gh = tallyHeight(h)
  const step = 0.26 * gh
  const groupW = 1.05 * gh + 6
  const full = Math.floor(count / 5)
  const rest = count % 5
  const last = rest ? (Math.min(4, rest) - 1) * step + 1.4 : 0
  return Math.max(0, Math.ceil(full * groupW - (rest ? 0 : 6) + last))
}

export const badgeRecipe = defineRecipe<BadgeParams>({
  id: 'badge',
  kind: 'chip',
  layers: ['rest', 'hover', 'focus'],
  lazy: ['focus'],
  pad: 12,
  draw(ink, { w, h }, { variant, size, tone = 'marker', tally, hoverable }, ctx) {
    const r = h / 2
    const calm = ctx.calm
    ctx.lazy('focus', (fink) => focusRing(fink, 0, 0, w, h, { r }))
    if (ctx.lazyOnly) return
    const body = pillPoly(0.5, 0.5, w - 1, h - 1)
    const fillTone: PaintKey = tone === 'marker' ? 'marker' : tone
    const labelBase = h / 2 + LABEL_PX[size] * 0.56

    ink.layer('rest', () => {
      const outlinePen = calm ? 'pencil.fine' : 'ink.fine'
      if (variant === 'default') {
        ink.part('fill', () => blobFill(ink, body, fillTone, { alpha: 0.9, mis: calm ? false : undefined }))
        box(ink, 0, 0, w, h, { pen: outlinePen, corner: r })
      } else if (variant === 'secondary') {
        ink.part(
          'fill',
          () => {
            highlight(ink, 2, h * 0.08, w - 4, h * 0.84, { k: 1 })
            return { dx: 0, dy: 0 }
          },
          'hl'
        )
      } else if (variant === 'destructive') {
        ink.part('fill', () => blobFill(ink, body, 'red', { alpha: 0.97 }))
        box(ink, 0, 0, w, h, { pen: calm ? 'red.fine' : 'redfelt', corner: r, opts: { width: 0.8 } })
      } else if (variant === 'outline') {
        box(ink, 0, 0, w, h, { pen: outlinePen, corner: r })
      }
      if (tally) {
        const gh = tallyHeight(h)
        const tw = tallyWidth(tally, h)
        const t = tallyLines(ink.next('tally'), (w - tw) / 2 + 0.8, (h - gh) / 2, tally, gh)
        ink.lines(t.lines, h < 24 ? 'ink.fine' : 'ink', { width: 1.05 })
      }
    })

    if (!hoverable) return
    ink.layer('hover', () => {
      if (variant === 'ghost') {
        ink.part('swipe', () => highlight(ink, 2, h * 0.08, w - 4, h * 0.84, { k: 1 }), 'hl')
        return
      }
      if (variant === 'link') {
        ink.part('swipe', () => underline(ink, w * 0.08, labelBase, w * 0.84, { pen: 'blue.brush', kind: 'single' }), 'top')
        return
      }
      if (variant === 'outline') wash(ink, body, 'hi', { alpha: 0.5 })
      if (calm) {
        box(ink, 1, 1, w - 2, h - 2, {
          pen: 'pencil.fine',
          corner: r,
          loose: 0.6,
          opts: { alpha: 0.7, simple: true },
        })
        return
      }
      const d = 3 + h / 40
      ink.lines([{ pts: [[r * 0.8 + d, h + d], [w - r * 0.7 + d, h + d]], o: RULER }], 'ink.fine', { width: 1.3 })
    })
  },
})
